    RUNTIME_ENV: runtimeEnvironment,
    DATABASE_ADAPTER: "postgres",
    OAUTH_ISSUER: manifest.public.appAuthority,
    OAUTH_RESOURCE: manifest.public.mcpResource,
    SKILLPLANE_TOPOLOGY: topology,
